// GENERATED — do not hand-edit.
//
// Inter and Iosevka, subset and embedded so the plugin does not depend on
// either being installed on the host. Each face is a woff2 cut down to the
// characters this UI draws: ASCII, Latin-1, quotes and dashes, plus box
// drawing, block shades and arrows for terminal output.
//
// Iosevka ships twice, on purpose:
//   OMP Iosevka       all OpenType features stripped
//   OMP Iosevka Code  `calt` retained, which is where Iosevka keeps its
//                     programming ligatures
//
// Only code blocks use the ligature cut. Terminal output, diffs and file paths
// stay on the plain family, because a shaped `->` or `=>` no longer matches
// the bytes on disk and that matters when the text is a log or a patch.
//
// Regenerate with fontTools:
//   pyftsubset <face>.woff2 --unicodes=U+0020-007E,U+00A0-00FF,U+2018-201F,\
//     U+2022,U+2026,U+2030,U+2039-203A,U+20AC,U+2190-2199,U+21B5,U+2212,\
//     U+2248,U+2260,U+2500-257F,U+2580-259F,U+25A0-25FF,U+2610-2612,\
//     U+2713-2717,U+00D7,U+00F7 --flavor=woff2 --no-hinting \
//     --layout-features=''      # plain
//     --layout-features=calt    # ligature cut

export interface EmbeddedFontFace {
  readonly family: string;
  readonly weight: string;
  readonly woff2Base64: string;
}

